class Solution {
public:
    int minFallingPathSum(vector<vector<int>>& matrix) {
        int n = matrix.size();
        vector<int> dp = matrix[0];
        for (int r = 1; r < n; ++r) {
            vector<int> nxt(n);
            for (int c = 0; c < n; ++c) {
                int left = c > 0 ? dp[c - 1] : 1e9;
                int mid = dp[c];
                int right = c < n - 1 ? dp[c + 1] : 1e9;
                nxt[c] = matrix[r][c] + min({left, mid, right});
            }
            dp = move(nxt);
        }
        return *min_element(dp.begin(), dp.end());
    }
};

class Solution {
    public int minFallingPathSum(int[][] matrix) {
        int n = matrix.length;
        int[] dp = matrix[0].clone();
        for (int r = 1; r < n; r++) {
            int[] nxt = new int[n];
            for (int c = 0; c < n; c++) {
                int left = c > 0 ? dp[c - 1] : Integer.MAX_VALUE;
                int mid = dp[c];
                int right = c < n - 1 ? dp[c + 1] : Integer.MAX_VALUE;
                nxt[c] = matrix[r][c] + Math.min(left, Math.min(mid, right));
            }
            dp = nxt;
        }
        int res = Integer.MAX_VALUE;
        for (int v : dp) res = Math.min(res, v);
        return res;
    }
}

var minFallingPathSum = function(matrix) {
    const n = matrix.length;
    let dp = [...matrix[0]];
    for (let r = 1; r < n; r++) {
        const nxt = new Array(n);
        for (let c = 0; c < n; c++) {
            const left = c > 0 ? dp[c - 1] : Infinity;
            const mid = dp[c];
            const right = c < n - 1 ? dp[c + 1] : Infinity;
            nxt[c] = matrix[r][c] + Math.min(left, mid, right);
        }
        dp = nxt;
    }
    return Math.min(...dp);
};
